import sys
input = sys.stdin.readline
for _ in range(int(input())):
	(N, M) = map(int, input().split())
	table = [0] * M
	t = []
	for i in range(M):
		(a, b) = map(int, input().split())
		t.append((a, b))
	cs = [0] * (M + 1)
	t.sort(key=lambda x: -x[0])
	for i in range(M):
		cs[i + 1] = cs[i] + t[i][0]
	res = cs[min(N, M)]
	for i in range(M):
		x = t[i][1]
		ok = 0
		ng = min(N, M) + 1
		while ng - ok > 1:
			m = (ok + ng) // 2
			if t[m - 1][0] > x:
				ok = m
			else:
				ng = m
		if ok - 1 >= i:
			res = max(res, cs[ok] + (N - ok) * x)
		elif N - ok > 0:
			res = max(res, cs[ok] + t[i][0] + (N - ok - 1) * x)
	print(res)
	input()
